CREATE DATABASE IF NOT EXISTS university_registration CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE university_registration;
CREATE TABLE IF NOT EXISTS Student(student_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,department VARCHAR(100) NOT NULL,major VARCHAR(100) NOT NULL,semester TINYINT UNSIGNED NOT NULL DEFAULT 1,academic_status ENUM('ACTIVE','INACTIVE','PROBATION') DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS Faculty(faculty_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,department VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS Course(course_id INT AUTO_INCREMENT PRIMARY KEY,course_code VARCHAR(20) NOT NULL UNIQUE,course_name VARCHAR(160) NOT NULL,description TEXT,credits TINYINT UNSIGNED NOT NULL,department VARCHAR(100) NOT NULL,CHECK(credits>=0));
CREATE TABLE IF NOT EXISTS Semester(semester_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,is_current BOOLEAN DEFAULT FALSE,CHECK(end_date>=start_date));
CREATE TABLE IF NOT EXISTS Section(section_id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,faculty_id INT NOT NULL,semester_id INT NOT NULL,section_number VARCHAR(12) NOT NULL,classroom VARCHAR(40) NOT NULL,schedule_day ENUM('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday') NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,capacity SMALLINT UNSIGNED NOT NULL,UNIQUE(course_id,semester_id,section_number),FOREIGN KEY(course_id) REFERENCES Course(course_id),FOREIGN KEY(faculty_id) REFERENCES Faculty(faculty_id),FOREIGN KEY(semester_id) REFERENCES Semester(semester_id),CHECK(end_time>start_time),CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS Users(user_id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','faculty','admin') NOT NULL,student_id INT NULL UNIQUE,faculty_id INT NULL UNIQUE,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(student_id) REFERENCES Student(student_id),FOREIGN KEY(faculty_id) REFERENCES Faculty(faculty_id));
CREATE TABLE IF NOT EXISTS Enrollment(student_id INT NOT NULL,section_id INT NOT NULL,enrollment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM('ENROLLED','WAITLISTED','DROPPED','COMPLETED') DEFAULT 'ENROLLED',grade VARCHAR(2),PRIMARY KEY(student_id,section_id),FOREIGN KEY(student_id) REFERENCES Student(student_id),FOREIGN KEY(section_id) REFERENCES Section(section_id));
CREATE TABLE IF NOT EXISTS Prerequisite(course_id INT NOT NULL,prerequisite_course_id INT NOT NULL,minimum_grade VARCHAR(2) DEFAULT 'D',PRIMARY KEY(course_id,prerequisite_course_id),FOREIGN KEY(course_id) REFERENCES Course(course_id),FOREIGN KEY(prerequisite_course_id) REFERENCES Course(course_id),CHECK(course_id<>prerequisite_course_id));
CREATE TABLE IF NOT EXISTS AcademicRecord(record_id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,grade VARCHAR(2) NOT NULL,completed_at DATE NOT NULL,UNIQUE(student_id,course_id),FOREIGN KEY(student_id) REFERENCES Student(student_id),FOREIGN KEY(course_id) REFERENCES Course(course_id));
CREATE TABLE IF NOT EXISTS Waitlist(waitlist_id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,section_id INT NOT NULL,status ENUM('WAITLISTED','PROMOTED','CANCELLED') DEFAULT 'WAITLISTED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,section_id),FOREIGN KEY(student_id) REFERENCES Student(student_id),FOREIGN KEY(section_id) REFERENCES Section(section_id));
CREATE TABLE IF NOT EXISTS RegistrationSettings(setting_id INT PRIMARY KEY,max_credits TINYINT UNSIGNED DEFAULT 24,registration_open BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS AuditLog(audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(50) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id BIGINT NULL,details VARCHAR(500) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES Users(user_id) ON DELETE SET NULL);
